import java.util.*;
import java.io.*;

public class Main {
    static final int N = 50, M = 50, K = 50;
    static int T = N + K + 1;
    static int N_ = N * T + 1;
    static int M_ = K + (M * 2 * K + N) * (T - 1);
    static final int INF = 0x3f3f3f3f;

    static int[] pi = new int[N_], kk = new int[N_], bb = new int[N_];
    static int[] pq = new int[1 + N_], iq = new int[N_], cnt = 0;

    static class Link {
        Link next;
        int j;
    }

    static Link[] aa = new Link[N], aa_ = new Link[N_];

    static int[] uu = new int[M_], vv = new int[M_], uv = new int[M_], cost = new int[M_], cost_ = new int[M_];
    static int[] cc = new int[M_ * 2];

    static int n_, m_;
    static int[] ii = new int[K];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        for (int h = 0; h < k; h++) {
            ii[h] = Integer.parseInt(br.readLine()) - 1;
        }

        for (int i = 0; i < N; i++) {
            aa[i] = new Link();
            aa[i].next = null;
        }
        for (int i = 0; i < N_; i++) {
            aa_[i] = new Link();
            aa_[i].next = null;
        }

        for (int h = 0; h < m; h++) {
            st = new StringTokenizer(br.readLine());
            int i = Integer.parseInt(st.nextToken()) - 1;
            int j = Integer.parseInt(st.nextToken()) - 1;
            add(i, j);
            add(j, i);
        }

        int t = n + k + 1;
        N_ = n * t + 1;
        m_ = 0;

        for (int i = 0; i < n; i++) {
            for (int s = 0; s < t - 1; s++) {
                int u = i * t + s;
                for (Link l = aa[i]; l != null; l = l.next) {
                    int j = l.j;
                    int v = j * t + s + 1;
                    for (int x = 1; x <= k; x++) {
                        link(u, v, 1, c + (x * 2 - 1) * d);
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int s = 0; s < t - 1; s++) {
                int u = i * t + s;
                int v = u + 1;
                link(u, v, k, i == 0 ? 0 : c);
            }
        }

        for (int h = 0; h < k; h++) {
            link(N_ - 1, ii[h] * t + 0, 1, 0);
        }

        System.out.println(edmonds_karp(N_ - 1, 0 * t + t - 1));
    }

    static int i2(int i) {
        i *= 2;
        if (i > cnt) return 0;
        if (i < cnt && (pi[pq[i + 1]] < pi[pq[i]] || (pi[pq[i + 1]] == pi[pq[i]] && kk[pq[i + 1]] < kk[pq[i]]))) return i + 1;
        return i;
    }

    static void pq_up(int u) {
        int i = iq[u], j;
        while (i > 1 && (pi[u] < pi[pq[j = i / 2]] || (pi[u] == pi[pq[j]] && kk[u] < kk[pq[j]]))) {
            pq[iq[pq[j]] = i] = pq[j];
            i = j;
        }
        pq[iq[u] = i] = u;
    }

    static void pq_dn(int u) {
        int i = iq[u], j;
        while ((j = i2(i)) != 0 && (pi[pq[j]] < pi[u] || (pi[pq[j]] == pi[u] && kk[pq[j]] < kk[u]))) {
            pq[iq[pq[j]] = i] = pq[j];
            i = j;
        }
        pq[iq[u] = i] = u;
    }

    static void pq_add(int u) {
        iq[u] = ++cnt;
        pq_up(u);
    }

    static int pq_remove_first() {
        int u = pq[1], v = pq[cnt--];
        iq[v] = 1;
        pq_dn(v);
        return u;
    }

    static void add(int i, int j) {
        Link l = new Link();
        l.j = j;
        l.next = aa[i].next;
        aa[i].next = l;
    }

    static void add_(int i, int h) {
        Link l = new Link();
        l.j = h;
        l.next = aa_[i].next;
        aa_[i].next = l;
    }

    static void link(int u, int v, int cap, int cos) {
        int h = m_++;
        uu[h] = u;
        vv[h] = v;
        uv[h] = u ^ v;
        cost[h] = cos;
        cc[h << 1] = cap;
        add_(u, h << 1);
        add_(v, (h << 1) ^ 1);
    }

    static void dijkstra(int s) {
        Arrays.fill(pi, 0, N_, INF);
        pi[s] = 0;
        pq_add(s);
        while (cnt > 0) {
            int u = pq_remove_first();
            for (Link l = aa_[u]; l != null; l = l.next) {
                int h_ = l.j, h = h_ >> 1, v = u ^ uv[h], p;
                if (cc[h_]) {
                    p = pi[u] + ((h_ & 1) == 0 ? cost_[h] : -cost_[h]);
                    if (pi[v] == INF) {
                        pi[v] = p;
                        kk[v] = kk[u] + 1;
                        bb[v] = h_;
                        pq_add(v);
                    } else if (pi[v] > p || (pi[v] == p && kk[v] > kk[u] + 1)) {
                        pi[v] = p;
                        kk[v] = kk[u] + 1;
                        bb[v] = h_;
                        pq_up(v);
                    }
                }
            }
        }
    }

    static void push(int s, int t) {
        for (int u = t; u != s; u ^= uv[bb[u]]) {
            int h_ = bb[u], h = h_ >> 1;
            cc[h_]--;
            cc[h_ ^ 1]++;
        }
    }

    static int edmonds_karp(int s, int t) {
        System.arraycopy(cost, 0, cost_, 0, m_);
        while (true) {
            dijkstra(s);
            if (pi[t] == INF) break;
            push(s, t);
            for (int h = 0; h < m_; h++) {
                int u = uu[h], v = vv[h];
                if (pi[u] != INF && pi[v] != INF) {
                    cost_[h] += pi[u] - pi[v];
                }
            }
        }
        int c = 0;
        for (int h = 0; h < m_; h++) {
            c += cost[h] * cc[h << 1 ^ 1];
        }
        return c;
    }
}
